      (r) =>
        r.url === '/api/products' &&
        r.params.getAll('attr')?.length === 2 &&
        r.params.getAll('attr')?.includes('Bauform:In-Ear') &&
        r.params.getAll('attr')?.includes('Kabellos:true')
    );
    expect(req.request.method).toBe('GET');
    req.flush(mockResponse);
